fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var sum = 0;
    var i = 1;
    while i < 41 {
        sum = sum + i;
        i = i + 1;
    }
    var product = 1;
    var j = 1;
    while j < 9 {
        product = product * j;
        j = j + 1;
    }
    io.write(text: sum.to_text().concat(other: " ").concat(other: product.to_text()))?;
    return Ok(unit);
}

fn sum_up_to(n: Int) -> Int {
    var total = 0;
    var i = 1;
    while i <= n {
        total = total + i;
        i = i + 1;
    }
    total
}

fn line_for(n: Int) -> String {
    n.to_text().concat(other: ": ").concat(other: sum_up_to(n).to_text()).concat(other: "\n")
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    io.write(text: line_for(12))?;
    io.write(text: line_for(30))?;
    io.write(text: line_for(7))?;
    return Ok(unit);
}
